<div class="card panel"><form class="form-grid compact" method="post" action="actions/save_user.php"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><label>Nama<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Jabatan<select name="role"><?php foreach(['asset_manager','head_equipment','planner','mechanic','logistics','viewer'] as $r): ?><option value="<?=$r?>"><?=e(role_label($r))?></option><?php endforeach; ?></select></label><label>Password Awal<input type="password" name="password" minlength="8" required></label><button class="btn primary">Tambah Pengguna</button></form></div>
